import {draftPriority} from './reviewer-controls.js?v=5';
import {renderAnalytics,miniRing} from './cms-charts.js?v=1';
let chartTab='checklists',chartDays=14;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups={tax:'Thuế',accounting:'Kế toán',labor:'Lao động',insurance:'Bảo hiểm',company:'Doanh nghiệp',commerce:'Thương mại',data:'Dữ liệu',fire:'PCCC',environment:'Môi trường',food:'Thực phẩm'};
const actions={LAW_DISCOVERY_UPDATED:'Cập nhật thiết lập Luật mới',LAW_DISCOVERY_RUN:'Quét văn bản mới',OBLIGATION_APPROVE:'Duyệt checklist',OBLIGATION_AUTO_APPROVED:'Tự duyệt hàng loạt',OBLIGATION_REJECT:'Trả lại checklist',OBLIGATION_SUBMITTED:'Gửi duyệt checklist',OBLIGATION_DRAFT_CREATED:'Tạo bản nháp',OBLIGATION_DRAFT_UPDATED:'Sửa bản nháp',OBLIGATION_RETIRED:'Ngừng phát hành',LAW_CHANGE_APPROVED:'Duyệt thay đổi luật',LAW_CHANGE_REJECTED:'Loại đề xuất',CATALOGUE_AUTO_PUBLISHED:'Cập nhật bộ checklist',CATALOGUE_RELEASED:'Phát hành bộ checklist'};
let h,data=null,loading=false,error='',key='';
export function configureOverview(hooks){h=hooks;}
export function invalidateOverview(){key='';data=null;}
async function load(){loading=true;error='';h.render();try{data=await h.api('/admin/overview');}catch(e){error=e.message||'Chưa tải được số liệu.';}finally{loading=false;h.render();}}
export function mountOverview(){if(!h||h.screen()!=='overview'){key='';return;}const next=h.account()?.user.id||'';if(next&&key!==next&&!loading){key=next;void load();}}
const nf=n=>new Intl.NumberFormat('vi-VN').format(n||0);
const date=x=>x?new Date(x).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}):'Chưa có';
function queueCard(title,summary,label,attrs){return `<article class="task-card overview-task"><div class="task-card-main"><div class="task-card-overline"><span>${label}</span></div><h3>${esc(title)}</h3><p>${esc(summary)}</p></div><button type="button" class="task-open" ${attrs} aria-label="${esc(title)}">${h.icon('arrow',19)}</button></article>`;}
function priority(o){const f=o.feedback||{},rows=[];
 if(f.OPEN)rows.push(queueCard(`${nf(f.OPEN)} phản hồi mới từ doanh nghiệp`,'Kiểm tra vấn đề doanh nghiệp gửi và trả lời ngay trong cuộc trao đổi.','PHẢN HỒI','data-ov="go" data-view="feedback"'));
 if(o.changes.readyToNotify)rows.push(queueCard(`${nf(o.changes.readyToNotify)} thay đổi đã có checklist để duyệt cảnh báo`,'Đối chiếu nội dung cảnh báo và phạm vi doanh nghiệp trước khi duyệt.','THAY ĐỔI LUẬT','data-ov="changes" data-status="PENDING"'));
 if(o.changes.relevant)rows.push(queueCard(`${nf(o.changes.relevant)} đề xuất liên quan checklist đã phát hành`,'Ưu tiên kiểm tra tác động tới các công việc doanh nghiệp đang dùng.','CẦN ĐỐI CHIẾU','data-ov="changes" data-status="PENDING"'));
 if(o.alerts.impactsFailed)rows.push(queueCard(`${nf(o.alerts.impactsFailed)} lượt đánh giá cảnh báo cần kiểm tra`,'Xem lỗi trước khi thử lại để tránh bỏ sót doanh nghiệp bị ảnh hưởng.','VẬN HÀNH','data-ov="changes" data-view="impacts"'));
 const sorted=[...o.obligations.queue].sort((a,b)=>(a.status==='IN_REVIEW'?0:1)-(b.status==='IN_REVIEW'?0:1)||draftPriority(a)-draftPriority(b)||a.title.localeCompare(b.title,'vi'));
 for(const v of sorted.slice(0,Math.max(2,5-rows.length)))rows.push(queueCard(v.title,`${groups[v.group]||'Khác'} · ${v.status==='IN_REVIEW'?'Đã gửi, chờ kiểm tra':'Bản nháp cần rà soát'}`,v.status==='IN_REVIEW'?'CHỜ DUYỆT':'BẢN NHÁP',`data-ov="version" data-id="${esc(v.id)}"`));
 return rows.length?`<div class="task-list">${rows.join('')}</div>`:'<div class="empty-state"><h3>Không còn việc chờ ưu tiên</h3><p>Bạn có thể kiểm tra danh sách nghĩa vụ và phản hồi doanh nghiệp.</p></div>';
}
export function renderOverview(){
 const header=h.pageTitle?h.pageTitle('KHÔNG GIAN QUẢN LÍ','Tổng quan','Theo dõi việc cần duyệt và những vấn đề doanh nghiệp gửi về.',`<button type="button" class="secondary-button" data-ov="refresh" ${loading?'disabled':''}>${h.icon('rotate',16)} ${loading?'Đang tải…':'Tải lại'}</button>`):'<h1>Tổng quan</h1>';
 if(!data)return `<section class="overview-workspace">${header}${error?`<p class="form-error" role="alert">${esc(error)}</p>`:'<p role="status">Đang tải số liệu…</p>'}</section>`;
 const o=data,ob=o.obligations,ch=o.changes,f=o.feedback||{},pending=ob.draft+ob.inReview,stats=[['Nghĩa vụ chờ duyệt',pending,'admin','Kiểm tra và hoàn thiện checklist'],['Thay đổi luật chờ xử lý',ch.pending,'changes','Đối chiếu văn bản và tác động'],['Phản hồi cần xử lý',(f.OPEN||0)+(f.IN_REVIEW||0),'feedback',`${nf(f.OPEN)} mới · ${nf(f.IN_REVIEW)} đang xử lý`],['Đã phát hành cho doanh nghiệp',ob.published,'admin',`${nf(ob.total)} nghĩa vụ trong thư viện`]];
 const rows=ob.groups.filter(g=>groups[g.group]&&(g.draft+g.inReview)>0).sort((a,b)=>(b.draft+b.inReview)-(a.draft+a.inReview));
 const latest=o.catalogue.latest;const denominators=[ob.total,ch.pending+ch.approved+ch.rejected,Object.values(f).reduce((a,b)=>a+Number(b||0),0),ob.total];
 return `<section class="overview-workspace">${header}${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="overview-stats">${stats.map(([label,value,view,hint],i)=>`<button type="button" class="overview-stat" data-ov="go" data-view="${view}"><span>${label}</span><span class="overview-stat-value"><strong>${nf(value)}</strong>${miniRing(value,denominators[i],label)}</span><small>${hint}</small>${h.icon('arrow',17)}</button>`).join('')}</div>${renderAnalytics(o,chartTab,chartDays)}<div class="dashboard-lower overview-columns"><section><div class="section-heading"><div><h2>Việc cần ưu tiên</h2><p>Phản hồi mới, thay đổi liên quan và checklist đang chờ kiểm tra.</p></div><button type="button" class="text-action" data-ov="go" data-view="admin">Xem phòng duyệt ${h.icon('arrow',16)}</button></div>${priority(o)}<div class="section-heading overview-group-heading"><div><h2>Nghĩa vụ theo nhóm</h2><p>Chọn nhóm để mở danh sách cần duyệt.</p></div></div><div class="overview-groups">${rows.map(g=>`<button type="button" data-ov="group" data-group="${g.group}"><span>${groups[g.group]}</span><strong>${nf(g.draft+g.inReview)} <small>cần duyệt</small></strong>${h.icon('arrow',16)}</button>`).join('')}</div></section><aside class="overview-rail"><section class="rail-panel"><span class="rail-kicker">BỘ CHECKLIST HIỆN HÀNH</span><h3>${nf(latest?.items??0)} checklist đang cung cấp</h3><p>${latest?'Cập nhật '+date(latest.publishedAt):'Chưa có bộ checklist được phát hành.'}</p><dl class="overview-facts"><div><dt>Chuyên gia duyệt</dt><dd>${nf(ob.reviewBasis?.expert)}</dd></div><div><dt>Tự duyệt, chưa thẩm định</dt><dd>${nf(ob.reviewBasis?.auto)}</dd></div><div><dt>Doanh nghiệp sử dụng</dt><dd>${nf(o.catalogue.companiesUsing)}</dd></div></dl>${ob.reviewBasis?.auto?`<p class="overview-attention">${nf(ob.reviewBasis.auto)} checklist tự duyệt vẫn cần chuyên gia thẩm định nội dung.</p>`:''}<button type="button" class="secondary-button" data-ov="go" data-view="admin">Kiểm tra checklist</button></section><section class="rail-panel"><span class="rail-kicker">TRAO ĐỔI VỚI DOANH NGHIỆP</span><h3>${nf(f.OPEN)} phản hồi mới</h3><p>Nhận báo cáo không phù hợp, khó hiểu hoặc lỗi thao tác. Kết quả xử lý hiển thị trực tiếp cho doanh nghiệp.</p><button type="button" class="secondary-button" data-ov="go" data-view="feedback">Mở phản hồi</button></section><p class="overview-updated">Số liệu cập nhật ${date(o.generatedAt)}.</p></aside></div><details class="overview-operations"><summary>Số liệu vận hành và hoạt động gần đây</summary><div class="overview-ops-grid"><section><h3>Cảnh báo và nguồn dữ liệu</h3><dl class="overview-facts"><div><dt>Thay đổi đã duyệt</dt><dd>${nf(ch.approved)}</dd></div><div><dt>Thông báo luật đã đến doanh nghiệp</dt><dd>${nf(o.alerts.alerts30)}</dd></div><div><dt>Nhắc hạn đã đến doanh nghiệp</dt><dd>${nf(o.alerts.reminders30)}</dd></div><div><dt>Cảnh báo đang giữ để kiểm tra</dt><dd>${nf(o.alerts.held30)}</dd></div></dl><p class="field-hint">Thông báo tính trong 30 ngày. Thay đổi đã duyệt không đồng nghĩa đã gửi thông báo.</p><p>${o.sources.watchEnabled?`${nf(o.sources.watchEnabled)} nguồn đang theo dõi`:'Thu thập văn bản tự động đang tạm dừng theo yêu cầu.'}</p></section><section><h3>Hoạt động gần đây</h3><ul class="overview-activity">${o.activity.slice(0,6).map(a=>`<li><strong>${esc(actions[a.action]||'Cập nhật nghiệp vụ')}</strong><span>${esc(a.actor)} · ${date(a.at)}</span></li>`).join('')||'<li>Chưa có hoạt động.</li>'}</ul></section></div></details></section>`;
}
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest('[data-ov]');if(!b||!h)return;const a=b.dataset.ov;if(a==='chart-tab'){chartTab=b.dataset.tab;const top=window.scrollY;h.render();window.scrollTo({top,behavior:'instant'});document.getElementById('cms-chart-tab-'+chartTab)?.focus({preventScroll:true});return;}if(a==='refresh')void load();if(a==='go')h.go(b.dataset.view);if(a==='group')h.openGroup(b.dataset.group,b.dataset.filter);if(a==='version')h.openVersion(b.dataset.id);if(a==='changes')h.openChanges({status:b.dataset.status,view:b.dataset.view,id:b.dataset.id});});

if(typeof document!=='undefined')document.addEventListener('change',e=>{if(!e.target.matches('[data-cms-range]')||!h)return;chartDays=Number(e.target.value)===7?7:14;const top=window.scrollY;h.render();window.scrollTo({top,behavior:'instant'});document.querySelector('[data-cms-range]')?.focus({preventScroll:true});});

if(typeof document!=='undefined')document.addEventListener('keydown',e=>{const b=e.target.closest('[data-ov="chart-tab"]');if(!b||!h||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=['checklists','changes','feedback','delivery'],i=tabs.indexOf(b.dataset.tab);e.preventDefault();document.getElementById('cms-chart-tab-'+tabs[e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4])?.click();});
